  };

  if (this.carouselVariant === 1) {
    // Variant 1: Classic Coverflow (3D rotate)
    if (isCenter) {
      style.transform = `translateX(0) scale(1) translateZ(50px)`;
      style.opacity = 1;
      style.filter = 'brightness(1)';
    } else {
      const sign = Math.sign(offset);
      style.transform = `translateX(${sign * 60}%) scale(0.8) translateZ(-100px) rotateY(${sign * -25}deg)`;
      style.opacity = 0.5;
      style.filter = 'brightness(0.6)';
      style.cursor = 'pointer';
    }
  } else if (this.carouselVariant === 2) {
    // Variant 2: Flat Stacked (No 3D rotation, just overlapping scale)
    if (isCenter) {
      style.transform = `translateX(0) scale(1)`;
      style.opacity = 1;
      style.filter = 'drop-shadow(0 20px 30px rgba(0,0,0,0.15))';
    } else {
      const sign = Math.sign(offset);
      style.transform = `translateX(${sign * 45}%) scale(0.85)`;
      style.opacity = 0.7;
      style.cursor = 'pointer';
    }
  } else if (this.carouselVariant === 3) {
    // Variant 3: Focus Blur (Modern soft interface)
    if (isCenter) {
      style.transform = `translateX(0) scale(1.05)`;
      style.opacity = 1;
      style.filter = 'blur(0px)';
    } else {
      const sign = Math.sign(offset);
      style.transform = `translateX(${sign * 55}%) scale(0.9)`;
      style.opacity = 0.4;
      style.filter = 'blur(4px)';
      style.cursor = 'pointer';
    }
  }

  if (absOffset > 1) {
    style.opacity = 0; // Hide elements further than 1 step away
    style.pointerEvents = 'none';
  }

  return style;
}

