// Helper method for orbit positioning
getOrbitTransform(orb: number): string {
  const time = Date.now() * 0.001; // Current time in seconds
  const speed = 0.5; // Orbit speed

  // Orb 1 orbits slightly faster and at a different radius
  if (orb === 1) {
    const x = Math.cos(time * speed) * 15;
    const y = Math.sin(time * speed) * 15;
    return `translate(${x}px, ${y}px)`;
  } 
  // Orb 2 orbits slower, opposite direction, larger radius
  else {
    const x = Math.sin(time * speed * -0.7) * 20;
    const y = Math.cos(time * speed * -0.7) * 20;
    return `translate(${x}px, ${y}px)`;
  }
}

getCarouselStyle(index: number): any {
  const total = this.programs.length;
  // Calculate shortest distance in a circular array
  let offset = index - this.activeProgramIndex;
  if (offset > Math.floor(total / 2)) offset -= total;
  if (offset < -Math.floor(total / 2)) offset += total;

  const absOffset = Math.abs(offset);
  const isCenter = offset === 0;

  let style: any = {
    transition: 'all 0.8s cubic-bezier(0.22, 1, 0.36, 1)',
    position: 'absolute',
    width: '300px',
    height: '360px',
    top: '0',
    left: 'calc(50% - 150px)', // Center horizontally
    zIndex: 10 - absOffset,
    transformOrigin: 'bottom center'
  };

  if (this.newsStage === 'detail') {
    if (isCenter) {
      // Move to the left, scale down slightly, flatten 3D perspective
      style.transform = `translateX(-40vw) scale(0.9) translateZ(0)`;
      style.opacity = 1;
      style.filter = 'brightness(1)';
      style.cursor = 'default';
    } else {
      // Hide all other cards
      style.transform = `translateX(${Math.sign(offset) * 112}%) scale(0.82) translateZ(-100px)`;
      style.opacity = 0;
      style.pointerEvents = 'none';
    }
    return style;
  }

  if (isCenter) {
    style.transform = `translateX(0) scale(1.08) translateZ(50px)`;
    style.opacity = 1;
    style.filter = 'brightness(1)';
  } else {
    const sign = Math.sign(offset);
    // Rimosso il rotateY perchè le immagini hanno già una prospettiva 3D nativa
    style.transform = `translateX(${sign * 112}%) scale(0.82) translateZ(-100px)`;
    style.opacity = 0.55;
    style.filter = 'brightness(0.7)';
    style.cursor = 'pointer';
  }

  if (absOffset > 1) {
    style.opacity = 0; // Hide elements further than 1 step away
    style.pointerEvents = 'none';
  }

  return style;
}

